"""IMAP/SMTP transport. PEEK never marks messages read; only explicit open does."""

import base64
import email
import hashlib
import imaplib
import re
import smtplib
import ssl
import time
from datetime import datetime, timedelta, timezone
from email import policy
from email.message import EmailMessage
from email.utils import format_datetime, make_msgid, parseaddr
from html.parser import HTMLParser

from app.i18n import message as system_message


class MailProtocolError(ValueError):
    """A safe, user-facing error generated by this adapter."""


def folder_wire(value):
    def encode(match):
        return (
            "&"
            + base64.b64encode(match.group().encode("utf-16-be"))
            .decode()
            .rstrip("=")
            .replace("/", ",")
            + "-"
        )

    encoded = re.sub(r"[^\x20-\x7e]+", encode, value.replace("&", "&-"))
    return '"' + encoded.replace("\\", "\\\\").replace('"', '\\"') + '"'


def folder_text(value):
    def decode(match):
        text = match.group(1)
        return (
            "&"
            if not text
            else base64.b64decode(
                text.replace(",", "/") + "=" * ((-len(text)) % 4)
            ).decode("utf-16-be")
        )

    return re.sub(r"&([^-]*)-", decode, value)


def connect(config):
    context = ssl.create_default_context()
    client = (
        imaplib.IMAP4_SSL(
            config["imap_host"], config["imap_port"], ssl_context=context, timeout=30
        )
        if config["imap_security"] == "ssl"
        else imaplib.IMAP4(config["imap_host"], config["imap_port"], timeout=30)
    )
    try:
        if config["imap_security"] == "starttls":
            client.starttls(ssl_context=context)
        client.login(config["username"], config["password"])
        return client
    except Exception:
        try:
            client.logout()
        except Exception:
            pass
        raise


def folders(client):
    status, rows = client.list()
    if status != "OK":
        raise MailProtocolError("无法读取邮箱文件夹")
    result = []
    for row in rows:
        if isinstance(row, tuple):
            row = row[0] + b" " + row[1]
        if not row:
            continue
        match = re.match(rb'\((.*?)\)\s+(?:"(.*?)"|NIL)\s+(.*)', row)
        if not match:
            raise MailProtocolError("邮箱返回了不支持的文件夹格式")
        raw_name = match[3].decode("utf-8", errors="replace")
        if raw_name.startswith('"') and raw_name.endswith('"'):
            raw_name = re.sub(r"\\(.)", r"\1", raw_name[1:-1])
        flags = match[1].decode().split()
        result.append(
            {
                "path": folder_text(raw_name),
                "delimiter": (match[2] or b"/").decode(),
                "flags": flags,
                "selectable": "\\noselect" not in {flag.casefold() for flag in flags},
            }
        )
    return result


def folder_validity(client, name):
    # Virtual folders may omit UIDVALIDITY. Never invent a value that could
    # accidentally associate a reused UID with another message.
    values = client.response("UIDVALIDITY")[1] or []
    for value in values:
        if isinstance(value, bytes) and value.isdigit():
            return value.decode()
    status, rows = client.status(folder_wire(name), "(UIDVALIDITY)")
    if status == "OK":
        for row in rows or []:
            match = (
                re.search(rb"\bUIDVALIDITY\s+(\d+)\b", row, re.I)
                if isinstance(row, bytes)
                else None
            )
            if match:
                return match[1].decode()
    raise MailProtocolError("邮箱未返回文件夹 UIDVALIDITY，无法安全同步：" + name)


class TextOnly(HTMLParser):
    def __init__(self):
        super().__init__()
        self.text = []

    def handle_data(self, data):
        self.text.append(data)


def parse_mail(raw):
    message = email.message_from_bytes(raw, policy=policy.default)
    plain = message.get_body(preferencelist=("plain",))
    html = message.get_body(preferencelist=("html",))
    body_html = html.get_content() if html else ""
    body_text = plain.get_content() if plain else ""
    if not body_text and body_html:
        stripped = TextOnly()
        stripped.feed(body_html)
        body_text = "\n".join(stripped.text)
    ident = str(message.get("Message-ID", "")).strip()
    return {
        "source_key": hashlib.sha256(
            (ident or hashlib.sha256(raw).hexdigest()).encode()
        ).hexdigest(),
        "message_id": ident,
        "subject": str(message.get("Subject", "")),
        "sender": str(message.get("From", "")),
        "recipients": str(message.get("To", "")),
        "cc": str(message.get("Cc", "")),
        "body_text": body_text[:200000],
        "body_html": body_html[:500000],
        "raw": raw,
    }


def matches(rule, mail):
    sender = parseaddr(mail["sender"])[1].casefold()
    wanted = rule["sender"].casefold().strip()
    sender_ok = not wanted or (
        sender.endswith(wanted) if wanted.startswith("@") else sender == wanted
    )
    return sender_ok and (
        not rule["keywords"]
        or any(
            word.casefold() in mail["subject"].casefold() for word in rule["keywords"]
        )
    )


def read_snapshot(client, known, cutoff, deadline=None):
    result, descriptions, count = [], folders(client), 0
    total_bytes, seen = 0, set()

    def check_time():
        if deadline and time.monotonic() > deadline:
            raise MailProtocolError("邮箱同步超时")

    for folder in descriptions:
        check_time()
        if not folder["selectable"]:
            continue
        if client.select(folder_wire(folder["path"]), readonly=True)[0] != "OK":
            raise MailProtocolError("无法打开文件夹：" + folder["path"])
        validity = folder_validity(client, folder["path"])
        status, rows = client.uid(
            "search",
            None,
            "UNDELETED",
            "SINCE",
            (cutoff - timedelta(days=1)).strftime("%d-%b-%Y"),
        )
        if status != "OK":
            raise MailProtocolError("无法搜索文件夹：" + folder["path"])
        uids = rows[0].split() if rows and rows[0] else []
        count += len(uids)
        if count > 10000:
            raise MailProtocolError("最近30天邮件超过10000封，请拆分邮箱账户")
        for offset in range(0, len(uids), 100):
            check_time()
            status, metadata = client.uid(
                "fetch",
                b",".join(uids[offset : offset + 100]),
                "(UID FLAGS INTERNALDATE)",
            )
            if status != "OK":
                raise MailProtocolError("读取邮件标记失败")
            for line in metadata:
                check_time()
                if not isinstance(line, bytes):
                    continue
                uid = re.search(rb"UID\s+(\d+)", line)
                date = re.search(rb'INTERNALDATE\s+"([^"]+)"', line)
                flags = re.search(rb"FLAGS\s+\(([^)]*)\)", line)
                if not uid or not date or flags is None:
                    raise MailProtocolError("邮件缺少收件时间或标记")
                received = datetime.strptime(
                    date[1].decode().strip(), "%d-%b-%Y %H:%M:%S %z"
                ).astimezone(timezone.utc)
                if received < cutoff:
                    continue
                locator = (folder["path"], validity, uid[1].decode())
                payload = known.get(locator)
                if payload is None:
                    status, data = client.uid("fetch", uid[1], "(BODY.PEEK[])")
                    raw = next(
                        (part[1] for part in data if isinstance(part, tuple)), None
                    )
                    if status != "OK" or raw is None:
                        raise MailProtocolError("读取邮件正文失败")
                    if len(raw) > 10_000_000:
                        raise MailProtocolError("邮件超过10MB，暂不支持同步")
                    payload = parse_mail(raw)
                if payload["source_key"] not in seen:
                    seen.add(payload["source_key"])
                    total_bytes += len(payload["raw"])
                    if total_bytes > 200_000_000:
                        raise MailProtocolError(
                            "最近30天邮件总大小超过200MB，暂无法完整同步"
                        )
                result.append(
                    {
                        **payload,
                        "folder": folder["path"],
                        "validity": validity,
                        "uid": uid[1].decode(),
                        "received_at": received,
                        "is_read": b"\\seen" in flags[1].lower().split(),
                    }
                )
    return descriptions, result


def move(client, source, uid, destination):
    if client.select(folder_wire(source))[0] != "OK":
        raise MailProtocolError("无法打开源文件夹")
    capabilities = {
        (value.decode("ascii") if isinstance(value, bytes) else value).upper()
        for value in client.capabilities
    }
    if "MOVE" in capabilities:
        if client.uid("MOVE", uid, folder_wire(destination))[0] != "OK":
            raise MailProtocolError("移动邮件失败")
    else:
        # Never EXPUNGE the whole mailbox: it could purge unrelated client deletions.
        if "UIDPLUS" not in capabilities:
            raise MailProtocolError("邮箱不支持安全移动邮件（需要 MOVE 或 UIDPLUS）")
        if client.uid("COPY", uid, folder_wire(destination))[0] != "OK":
            raise MailProtocolError("复制邮件失败")
        if client.uid("STORE", uid, "+FLAGS.SILENT", "(\\Deleted)")[0] != "OK":
            raise MailProtocolError("更新源邮件标记失败")
        if client.uid("EXPUNGE", uid)[0] != "OK":
            raise MailProtocolError("移除源邮件副本失败")


def sync(config, known, rules, cutoff):
    deadline = time.monotonic() + 600
    with connect(config) as client:
        descriptions, rows = read_snapshot(client, known, cutoff, deadline)
        original_dates = {}
        for row in rows:
            key = row["source_key"]
            original_dates[key] = min(
                original_dates.get(key, row["received_at"]), row["received_at"]
            )
        moved, matched = False, {}
        for row in rows:
            if time.monotonic() > deadline:
                raise MailProtocolError("邮箱同步超时")
            for rule in rules:
                if matches(rule, row):
                    matched[row["source_key"]] = rule["id"]
                    if row["folder"] != rule["destination"]:
                        move(client, row["folder"], row["uid"], rule["destination"])
                        moved = True
                    break
        if moved:
            known = {(row["folder"], row["validity"], row["uid"]): row for row in rows}
            descriptions, rows = read_snapshot(client, known, cutoff, deadline)
        for row in rows:
            row["rule_id"] = matched.get(row["source_key"])
            row["received_at"] = min(
                row["received_at"],
                original_dates.get(row["source_key"], row["received_at"]),
            )
        return descriptions, rows


def create_folder(config, name):
    with connect(config) as client:
        if client.create(folder_wire(name))[0] != "OK":
            raise MailProtocolError("创建邮箱文件夹失败")


def mark_read(config, locations):
    with connect(config) as client:
        for location in locations:
            if client.select(folder_wire(location["folder"]))[0] != "OK":
                raise MailProtocolError("无法打开邮件文件夹")
            validity = folder_validity(client, location["folder"])
            if validity != location["validity"]:
                raise MailProtocolError("邮箱状态已变化，请重新收取")
            if (
                client.uid("STORE", location["uid"], "+FLAGS.SILENT", "(\\Seen)")[0]
                != "OK"
            ):
                raise MailProtocolError("同步已读状态失败")


def send(config, body, sent_folder):
    message = EmailMessage()
    message["From"] = config["address"]
    message["To"] = ", ".join(body["to"])
    if body["cc"]:
        message["Cc"] = ", ".join(body["cc"])
    message["Subject"] = body["subject"]
    message["Date"] = format_datetime(datetime.now(timezone.utc))
    message["Message-ID"] = make_msgid()
    if body.get("in_reply_to"):
        message["In-Reply-To"] = body["in_reply_to"]
        message["References"] = body["in_reply_to"]
    message.set_content(
        body["text"] or "Please view this message in an HTML-capable email client."
    )
    html = body["html"]
    inline = []

    def image(match):
        mime, data = match.group(1), match.group(2)
        content = base64.b64decode(data, validate=True)
        if len(content) > 5_000_000:
            raise MailProtocolError("正文图片超过5MB")
        cid = make_msgid()
        inline.append((cid, mime, content))
        return 'src="cid:' + cid[1:-1] + '"'

    html = re.sub(
        r'src="data:image/(png|jpeg|gif|webp);base64,([A-Za-z0-9+/=]+)"', image, html
    )
    message.add_alternative(html, subtype="html")
    for cid, subtype, content in inline:
        message.get_payload()[-1].add_related(
            content, maintype="image", subtype=subtype, cid=cid
        )
    for attachment in body["attachments"]:
        message.add_attachment(
            base64.b64decode(attachment["data"], validate=True),
            maintype="application",
            subtype="octet-stream",
            filename=attachment["name"],
        )
    raw = message.as_bytes()
    if len(raw) > 15_000_000:
        raise MailProtocolError("邮件总大小超过15MB")
    recipients = body["to"] + body["cc"] + body["bcc"]
    context = ssl.create_default_context()
    with (
        smtplib.SMTP_SSL(
            config["smtp_host"], config["smtp_port"], timeout=30, context=context
        )
        if config["smtp_security"] == "ssl"
        else smtplib.SMTP(config["smtp_host"], config["smtp_port"], timeout=30)
    ) as client:
        if config["smtp_security"] == "starttls":
            client.ehlo()
            client.starttls(context=context)
            client.ehlo()
        client.login(config["username"], config["password"])
        refused = client.sendmail(config["address"], recipients, raw)
    warning = system_message("errors.mailRecipientsRefused") if refused else ""
    if sent_folder:
        try:
            with connect(config) as client:
                if (
                    client.append(folder_wire(sent_folder), "(\\Seen)", None, raw)[0]
                    != "OK"
                ):
                    raise MailProtocolError()
        except Exception:
            warning = warning or system_message("errors.mailCopyFailed")
    else:
        warning = warning or system_message("errors.mailCopyMissing")
    return {
        "message_id": str(message["Message-ID"]),
        "warning": warning,
        "refused": list(refused),
    }
